def norm360(a):
    return a % 360.0


def jd_ut(y, m, d, h):
    if m <= 2:
        y -= 1
        m += 12
    A = y // 100
    B = 2 - A + A // 4
    return math.floor(365.25 * (y + 4716)) + math.floor(30.6001 * (m + 1)) + d + B - 1524.5 + h / 24


def gmst_deg(J):
    T = (J - 2451545) / 36525
    return norm360(280.46061837 + 360.98564736629 * (J - 2451545) + 0.000387933 * T * T)


def vec(ra, dec):
    return [math.cos(dec * DEG) * math.cos(ra * DEG), math.cos(dec * DEG) * math.sin(ra * DEG), math.sin(dec * DEG)]


def radec(v):
    n = math.sqrt(sum(x * x for x in v))
    return norm360(math.atan2(v[1], v[0]) / DEG), math.asin(v[2] / n) / DEG


def mv(M, v):
    return [M[i][0] * v[0] + M[i][1] * v[1] + M[i][2] * v[2] for i in range(3)]


def mvT(M, v):
    return [M[0][i] * v[0] + M[1][i] * v[1] + M[2][i] * v[2] for i in range(3)]


def dot(a, b):
    return a[0] * b[0] + a[1] * b[1] + a[2] * b[2]


def unit(v):
    n = math.sqrt(dot(v, v))
    return [x / n for x in v]


def sep(a, b):
    return math.acos(max(-1.0, min(1.0, dot(unit(a), unit(b))))) / DEG


def precession(J):
    T = (J - 2451545) / 36525
    a = DEG / 3600
    z = (2306.2181 * T + 1.09468 * T * T) * a
    ze = (2306.2181 * T + 0.30188 * T * T) * a
    th = (2004.3109 * T - 0.42665 * T * T) * a
    cz, sz, ce, se, ct, st = math.cos(z), math.sin(z), math.cos(ze), math.sin(ze), math.cos(th), math.sin(th)
    return [[cz * ct * ce - sz * se, -cz * ct * se - sz * ce, -cz * st], [sz * ct * ce + cz * se, -sz * ct * se + cz * ce, -sz * st], [st * ce, -st * se, ct]]


EPS = 23.4393 * DEG


def ecl2eq(v):
    return [v[0], v[1] * math.cos(EPS) - v[2] * math.sin(EPS), v[1] * math.sin(EPS) + v[2] * math.cos(EPS)]


ELEM = {"earth": [1.00000261, 0.00000562, 0.01671123, -0.00004392, -0.00001531, -0.01294668, 100.46457166, 35999.37244981, 102.93768193, 0.32327364, 0, 0],
        "jupiter": [5.20288700, -0.00011607, 0.04838624, -0.00013253, 1.30439695, -0.00183714, 34.39644051, 3034.74612775, 14.72847983, 0.21252668, 100.47390909, 0.20469106],
        "saturn": [9.53667594, -0.00125060, 0.05386179, -0.00050991, 2.48599187, 0.00193609, 49.95424423, 1222.49362201, 92.59887831, -0.41897216, 113.66242448, -0.28867794],
        "mars": [1.52371034, 0.00001847, 0.09339410, 0.00007882, 1.84969142, -0.00813131, -4.55343205, 19140.30268499, -23.94362959, 0.44441088, 49.55953891, -0.29257343],
        "venus": [0.72333566, 0.00000390, 0.00677672, -0.00004107, 3.39467605, -0.00078890, 181.97909950, 58517.81538729, 131.60246718, 0.00268329, 76.67984255, -0.27769418],
        "mercury": [0.38709927, 0.00000037, 0.20563593, 0.00001906, 7.00497902, -0.00594749, 252.25032350, 149472.67411175, 77.45779628, 0.16047689, 48.33076593, -0.12534081]}
PL_MAG = {"jupiter": -2.8, "saturn": 0.6, "mars": 1.2, "venus": -4.0}
PL_BV = {"jupiter": 0.85, "saturn": 1.05, "mars": 1.5, "venus": 0.8}


def helio(p, J):
    T = (J - 2451545) / 36525
    E0 = ELEM[p]
    el = [E0[2 * i] + E0[2 * i + 1] * T for i in range(6)]
    a, e, I, L, w, O = el[0], el[1], el[2] * DEG, el[3], el[4], el[5]
    om, M = (w - O) * DEG, norm360(L - w) * DEG
    E = M + e * math.sin(M)
    for _ in range(8):
        E -= (E - e * math.sin(E) - M) / (1 - e * math.cos(E))
    xp, yp, Or = a * (math.cos(E) - e), a * math.sqrt(1 - e * e) * math.sin(E), O * DEG
    co, so, cO, sO, cI, sI = math.cos(om), math.sin(om), math.cos(Or), math.sin(Or), math.cos(I), math.sin(I)
    return [(co * cO - so * sO * cI) * xp + (-so * cO - co * sO * cI) * yp, (co * sO + so * cO * cI) * xp + (-so * sO + co * cO * cI) * yp, so * sI * xp + co * sI * yp]


def planet_geo(p, J):
    e = helio("earth", J)
    Jt, g = J, None
    for _ in range(2):
        h = helio(p, Jt)
        g = [h[i] - e[i] for i in range(3)]
        Jt = J - math.sqrt(dot(g, g)) * 0.0057755
    return unit(ecl2eq(g))


def sun_geo(J):
    e = helio("earth", J)
    return unit(ecl2eq([-e[0], -e[1], -e[2]]))


def moon_geo(J):
    T = (J - 2451545) / 36525
    Lp = norm360(218.3164477 + 481267.88123421 * T)
    D = norm360(297.8501921 + 445267.1114034 * T) * DEG
    M = norm360(357.5291092 + 35999.0502909 * T) * DEG
    Mp = norm360(134.9633964 + 477198.8675055 * T) * DEG
    F = norm360(93.2720950 + 483202.0175233 * T) * DEG
    lon = (Lp + 6.288774 * math.sin(Mp) + 1.274027 * math.sin(2 * D - Mp) + 0.658314 * math.sin(2 * D) + 0.213618 * math.sin(2 * Mp) - 0.185116 * math.sin(M)
           - 0.114332 * math.sin(2 * F) + 0.058793 * math.sin(2 * D - 2 * Mp) + 0.057066 * math.sin(2 * D - M - Mp) + 0.053322 * math.sin(2 * D + Mp) + 0.045758 * math.sin(2 * D - M))
    lat = (5.128122 * math.sin(F) + 0.280602 * math.sin(Mp + F) + 0.277693 * math.sin(Mp - F) + 0.173237 * math.sin(2 * D - F) + 0.055413 * math.sin(2 * D - Mp + F)
           + 0.046271 * math.sin(2 * D - Mp - F))
    km = 385000.56 - 20905.355 * math.cos(Mp) - 3699.111 * math.cos(2 * D - Mp) - 2955.968 * math.cos(2 * D) - 569.925 * math.cos(2 * Mp)
    return ecl2eq(vec(lon - 1.396971 * T, lat)), km


def moon_topo(J):
    v, km = moon_geo(J)
    lst = norm360(gmst_deg(J) + SITE["lon"])
    P = precession(J)
    o = mvT(P, vec(lst, SITE["lat"]))
    R = 6378 / km
    t = [v[i] - R * o[i] for i in range(3)]
    n = math.sqrt(dot(t, t))
    return [x / n for x in t], km * n


def hor_matrix(J):
    P = precession(J)
    th = norm360(gmst_deg(J) + SITE["lon"]) * DEG
    p = SITE["lat"] * DEG
    c, s = math.cos(th), math.sin(th)
    R = [[-s, c, 0], [-math.sin(p) * c, -math.sin(p) * s, math.cos(p)], [math.cos(p) * c, math.cos(p) * s, math.sin(p)]]
    return [[sum(R[i][k] * P[k][j] for k in range(3)) for j in range(3)] for i in range(3)]


def altaz(h):
    return math.asin(max(-1.0, min(1.0, h[2]))) / DEG, norm360(math.atan2(h[0], h[1]) / DEG)


def hvec(alt, az):
    return [math.sin(az * DEG) * math.cos(alt * DEG), math.cos(az * DEG) * math.cos(alt * DEG), math.sin(alt * DEG)]


def refr(a):
    return 1.02 / math.tan((a + 10.3 / (a + 5.11)) * DEG) / 60 if a > -2 else 0.0


def airmass(a):
    a = max(0.5, a)
    return 1 / (math.sin(a * DEG) + 0.50572 * (a + 6.07995) ** -1.6364)


def tri_area(a, b, c):
    a, b, c = unit(a), unit(b), unit(c)
    cr = [b[1] * c[2] - b[2] * c[1], b[2] * c[0] - b[0] * c[2], b[0] * c[1] - b[1] * c[0]]
    return 2 * math.atan2(abs(dot(a, cr)), 1 + dot(a, b) + dot(b, c) + dot(c, a)) / DEG / DEG


def nL(V):
    return 34.08 * math.exp(20.7233 - 0.92104 * V)


def mag_of(B):
    return (20.7233 - math.log(B / 34.08)) / 0.92104


def moon_sky(rho, z, zm, phase):
    """Moonlight on the sky, nanolamberts (Krisciunas & Schaefer 1991)."""
    if zm >= 90:
        return 0.0
    I = 10 ** (-0.4 * (3.84 + 0.026 * abs(phase) + 4e-9 * phase ** 4))
    f = 10 ** 5.36 * (1.06 + math.cos(rho * DEG) ** 2) + 10 ** (6.15 - max(rho, 2) / 40)
    X = lambda zz: 1 / math.sqrt(1 - 0.96 * math.sin(zz * DEG) ** 2)
    return f * I * 10 ** (-0.4 * K_EXT * X(zm)) * (1 - 10 ** (-0.4 * K_EXT * X(min(z, 89.5))))


def nelm(q):
    return 7.93 - 5 * math.log10(10 ** (4.316 - q / 5) + 1)


def _stars():
    raw = base64.b64decode(STARDATA)
    out = []
    for ra, de, v, bv in struct.iter_unpack("<HhhB", raw):
        out.append([vec(ra / 180, de / 360), v / 100, bv / 80 - 0.5])
    return out



STARS = _stars()


def bv_rgb(bv):
    t = max(-0.4, min(2.0, bv))
    if t < 0.4:
        r, g, b = 0.72 + 0.7 * (t + 0.4), 0.8 + 0.4 * (t + 0.4), 1.0
    else:
        r, g, b = 1.0, 1.05 - 0.28 * (t - 0.4), 1 - 0.45 * (t - 0.4)
    return min(1, r), min(1, g), max(0.35, min(1, b))


def hexc(r, g, b):
    return "#%02x%02x%02x" % (int(max(0, min(255, r))), int(max(0, min(255, g))), int(max(0, min(255, b))))




def unit3(v):
    n = math.sqrt(dot(v, v))
    return [x / n for x in v]


def lam_of(v):
    e = 23.4393 * DEG
    return norm360(math.atan2(v[1] * math.cos(e) + v[2] * math.sin(e), v[0]) / DEG)


def ecl_vec(lam, beta):
    e = 23.4393 * DEG
    c = math.cos(beta * DEG)
    x, y, z = c * math.cos(lam * DEG), c * math.sin(lam * DEG), math.sin(beta * DEG)
    return [x, y * math.cos(e) - z * math.sin(e), y * math.sin(e) + z * math.cos(e)]


def body(p, J):
    return unit3(sun_geo(J) if p == "sun" else planet_geo(p, J))


def elong(J):
    return norm360(lam_of(moon_geo(J)[0]) - lam_of(sun_geo(J)))


def ymd(J):
    z = math.floor(J + 0.5)
    a = math.floor((z - 1867216.25) / 36524.25)
    b = z + 1 + a - math.floor(a / 4) + 1524
    c = math.floor((b - 122.1) / 365.25)
    d = math.floor(365.25 * c)
    e = math.floor((b - d) / 30.6001)
    day = b - d - math.floor(30.6001 * e)
    m = e - 1 if e < 14 else e - 13
    return (c - 4716 if m > 2 else c - 4715), m, day


MONTHS = T(["1월", "2월", "3월", "4월", "5월", "6월", "7월", "8월", "9월", "10월", "11월", "12월"],
           ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"])


def fmt_d(J):
    y, m, d = ymd(J)
    return T("%d년 %d월 %d일" % (y, m, d), "%d %s %d" % (d, MONTHS[m - 1][:3], y))


# ---- constellations: the IAU boundaries, point in polygon with the RA unwrapped along each ring
def in_ring(r, ra, de):
    X = [r[0][0]]
    for i in range(1, len(r)):
        X.append(X[-1] + (r[i][0] - r[i - 1][0] + 540) % 360 - 180)
    lo, hi = min(X), max(X)
    for k in (-360, 0, 360):
        x0 = ra + k
        if x0 < lo or x0 > hi:
            continue
        c = False
        j = len(r) - 1
        for i in range(len(r)):
            yi, yj = r[i][1], r[j][1]
            if (yi > de) != (yj > de):
                if X[i] + (de - yi) / (yj - yi) * (X[j] - X[i]) > x0:
                    c = not c
            j = i
        if c:
            return True
    return False


def const_of(v):
    ra, de = radec(v)
    for c, rings in BOUNDS.items():
        for r in rings:
            if in_ring(r, ra, de):
                return c
    return "?"


# ---- question 8: the same clock hour every evening; the sky turns only by the day's sidereal gain
SID = 0.98565 / 360.98565


def frame_hm(J0, J):
    return hor_matrix(J0 + (J - J0) * SID)


def moon_at(J0, J):
    v, km = moon_geo(J)
    Jf = J0 + (J - J0) * SID
    o = mvT(precession(J), vec(norm360(gmst_deg(Jf) + SITE["lon"]), SITE["lat"]))
    R = 6378 / km
    return unit3([v[i] - R * o[i] for i in range(3)])


class Rand:
    def __init__(self, seed):
        self.x = seed % 2147483646 + 1
        for _ in range(7):
            self()

    def __call__(self):
        self.x = (self.x * 16807) % 2147483647
        return self.x / 2147483647


def try_sc8(y, m, seed):
    J = jd_ut(y, m, 1, 0)
    while not (elong(J) < 90 <= elong(J + 0.25)):
        J += 0.25
    Jfq = J
    for k in range(20):
        h = 0.25 / 2 ** (k + 1)
        if elong(Jfq + h) < 90:
            Jfq += h
    Jfm = Jfq + 5
    while not (elong(Jfm) < 180 <= elong(Jfm + 0.25)):
        Jfm += 0.25
    d0 = ymd(Jfq - 2.5)
    hour = 17.0
    while hour < 24:
        Jh = jd_ut(d0[0], d0[1], d0[2], hour - SITE["tz"])
        if altaz(mv(hor_matrix(Jh), sun_geo(Jh)))[0] < -15:
            break
        hour += 0.5
    if hour >= 23:
        return None
    J0 = jd_ut(d0[0], d0[1], d0[2], hour - SITE["tz"])
    days = math.floor(Jfm - J0 + 0.6)
    t = 0.0
    while t <= days:
        if altaz(mv(frame_hm(J0, J0 + t), moon_at(J0, J0 + t)))[0] < 3:
            return None
        t += 0.5
    return {"kind": 8, "seed": seed, "J0": J0, "days": days, "hour": hour, "Jfq": Jfq, "Jfm": Jfm}


def scene8(seed):
    r = Rand(seed)
    for k in range(60):
        y = 2015 if seed == 2015 and not k else 1995 + int(r() * 41)
        m = 12 if seed == 2015 and not k else 1 + int(r() * 12)
        s = try_sc8(y, m, seed)
        if s:
            return s
    return try_sc8(2015, 12, seed)


def scene9(seed):
    def pick(J0, days):
        lc = lam_of(sun_geo(J0 + days / 2))
        t = 0
        while t <= days:
            for p in ("mars", "venus"):
                if abs((lam_of(planet_geo(p, J0 + t)) - lc + 540) % 360 - 180) > 62:
                    return None
            t += 4
        return lc
    if seed == 2015:
        J0, days = jd_ut(2015, 8, 1, 0), 80
        lc = pick(J0, days)
        return {"kind": 9, "seed": seed, "J0": J0, "days": days, "lc": lc if lc is not None else lam_of(sun_geo(J0 + 40))}
    r = Rand(seed)
    for _ in range(400):
        J0 = jd_ut(1995 + int(r() * 41), 1, 1, 0) + int(r() * 365)
        days = 60 + int(r() * 41)
        lc = pick(J0, days)
        if lc is not None:
            return {"kind": 9, "seed": seed, "J0": J0, "days": days, "lc": lc}
    return scene9(2015)


def key8(s):
    m = ymd(s["J0"] + s["days"] / 2)[1]
    months = set(ymd(s["J0"] + t)[1] for t in range(int(s["days"]) + 1))
    return m, months


def key9(s):
    def path(p):
        L = []
        t = 0.0
        while t <= s["days"]:
            c = const_of(body(p, s["J0"] + t))
            if not L or L[-1] != c:
                L.append(c)
            t += 0.5
        return L
    return {"mars": path("mars"), "venus": path("venus"), "sun": path("sun")}


def parse_md(s):
    import re
    mt = re.match(r"^\s*(\d{1,2})\s*[/.\-\s월]\s*(\d{1,2})", s or "")
    if not mt:
        return None
    mo, d = int(mt.group(1)), int(mt.group(2))
    if not (1 <= mo <= 12 and 1 <= d <= 31):
        return None
    return sum((31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)[:mo - 1]) + d - 1


def doy(J):
    _, m, d = ymd(J)
    return sum((31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)[:m - 1]) + d - 1


def ddays(a, b):
    x = abs(a - b) % 365
    return min(x, 365 - x)


def set_of(s):
    import re
    return set(w[0].upper() + w[1:3].lower() for w in re.split(r"[^A-Za-z]+", s or "") if w)


def cmp_set(user, truth):
    U, Tr = set_of(user), set(c for c in truth if c != "?")
    if not U:
        return ""
    miss, extra = sorted(Tr - U), sorted(U - Tr)
    if not miss and not extra:
        return " ✓"
    out = []
    if miss:
        out.append(T("빠짐: ", "missing: ") + ", ".join(miss))
    if extra:
        out.append(T("틀림: ", "wrong: ") + ", ".join(extra))
    return " — " + "; ".join(out)


