    # ---- storage
    def load(self):
        try:
            with open(SAVE, encoding="utf-8") as f:
                d = json.load(f)
            d.setdefault("sheet", {})
            d.setdefault("seeds", {"8": 2015, "9": 2015})
            return d
        except (OSError, ValueError):
            return {"sheet": {}, "seeds": {"8": 2015, "9": 2015}}

    def store(self):
        try:
            with open(SAVE, "w", encoding="utf-8") as f:
                json.dump(self.data, f, ensure_ascii=False)
        except OSError:
            pass

    # ---- the round
    def set_kind(self, k):
        self.kind = k
        for kk, b in self.tabb.items():
            b.configure(bg="#f2c14e" if kk == k else "#2b2f36", fg="#1c2027" if kk == k else "#e8eef2")
        self.q.configure(state="normal")
        self.q.delete("1.0", "end")
        self.q.insert("end", Q[k])
        self.q.configure(state="disabled")
        self.sheet8.pack_forget()
        self.sheet9.pack_forget()
        self.solb.pack_forget()
        self.sol.pack_forget()
        (self.sheet8 if k == 8 else self.sheet9).pack(fill="x")
        self.solb.pack(fill="x", padx=10, pady=(14, 4))
        self.sol.pack(fill="both", expand=True, padx=10)
        self.solved = False
        self.sol.configure(state="normal")
        self.sol.delete("1.0", "end")
        self.sol.configure(state="disabled")
        self.slider.set(int(self.R[k]["frac"] * 1000))

    def timeline(self):
        P = PROTO[self.kind]
        return [("read", P["read"]), ("play1", P["play"]), ("gap", 5), ("hold0", P["hold"]), ("play2", P["play"]), ("hold1", P["hold"]), ("write", P["write"])]

    def start(self):
        R = self.R[self.kind]
        R.update(phase="run", t0=time.time(), play=False)
        self.solved = False
        self.sol.configure(state="normal")
        self.sol.delete("1.0", "end")
        self.sol.configure(state="disabled")

    def skip(self):
        R = self.R[self.kind]
        if R["phase"] == "run":
            el = time.time() - R["t0"]
            R["t0"] -= max(0, PROTO[self.kind]["read"] - el)

    def new_scene(self, seed):
        k = self.kind
        if self.R[k]["phase"] == "run":
            return
        self.data["seeds"][str(k)] = seed
        self.store()
        self.scn[k] = scene8(seed) if k == 8 else scene9(seed)
        self.keyc.pop(k, None)
        self.R[k].update(phase="idle", frac=0.0, play=False)
        self.slider.set(0)
        if self.solved:
            self.write_sol()

    def fresh(self):
        self.new_scene(random.randint(1, 2000000000))

    def base(self):
        self.new_scene(2015)

    def toggle(self):
        R = self.R[self.kind]
        if R["phase"] == "run":
            return
        if R["frac"] >= 1:
            R["frac"] = 0.0
        R["play"] = not R["play"]

    def slide(self, v):
        R = self.R[self.kind]
        if R["phase"] != "run" and not R.get("from_loop"):
            R["frac"] = int(v) / 1000
            R["play"] = False

    def loop(self):
        now = time.time()
        dt = now - self.last
        self.last = now
        R = self.R[self.kind]
        P = PROTO[self.kind]
        if R["phase"] == "run":
            t = now - R["t0"]
            label, left = "done", 0
            for k, d in self.timeline():
                if t < d:
                    label, left = k, d - t
                    break
                t -= d
            if label == "done":
                R["phase"] = "done"
                R["frac"] = 1.0
            else:
                R["stage"], R["left"] = label, left
                R["frac"] = 1 - left / P["play"] if label in ("play1", "play2") else 0.0 if label in ("hold0", "read") else 1.0
        elif R["play"]:
            R["frac"] = min(1.0, R["frac"] + dt / P["play"])
            if R["frac"] >= 1:
                R["play"] = False
        if R["phase"] != "run":
            R["from_loop"] = True
            self.slider.set(int(R["frac"] * 1000))
            R["from_loop"] = False
        if R["phase"] == "run":
            s = int(R["left"])
            self.status.configure(text="%s · %d:%02d" % (STAGES[R["stage"]], s // 60, s % 60))
        else:
            self.status.configure(text=T("끝났습니다. 아래 막대로 다시 볼 수 있습니다.", "Finished. The slider below replays it.") if R["phase"] == "done" else T("‘라운드 시작’을 누르면 시험처럼 진행됩니다.", "‘Start the round’ runs it like the examination."))
        self.bplay.configure(text=T("멈춤", "Pause") if R["play"] else T("재생", "Play"))
        self.redraw()
        self.root.after(80 if (R["phase"] == "run" or R["play"]) else 250, self.loop)

    def move(self, e):
        if not self.drag:
            return
        x0, y0, v0 = self.drag
        v = self.view[self.kind]
        k = v["fov"] / max(100, self.cv.winfo_width())
        if self.kind == 8:
            v["az"] = norm360(v0["az"] - (e.x - x0) * k)
            v["alt"] = max(0.0, min(85.0, v0["alt"] + (e.y - y0) * k))
        else:
            v["dl"] = v0["dl"] + (e.x - x0) * k
            v["db"] = max(-60.0, min(60.0, v0["db"] + (e.y - y0) * k))

    def zoom(self, d):
        v = self.view[self.kind]
        v["fov"] = max(60.0, min(200.0, v["fov"] * (1.08 if d > 0 else 1 / 1.08)))

    # ---- the dome
    def basis(self, f, up):
        u = unit3([up[i] - dot(up, f) * f[i] for i in range(3)])
        r = [f[1] * u[2] - f[2] * u[1], f[2] * u[0] - f[0] * u[2], f[0] * u[1] - f[1] * u[0]]
        return f, u, r, (self.W / 2) / (2 * math.tan(self.view[self.kind]["fov"] / 4 * DEG))

    def proj(self, B, x):
        f, u, r, s = B
        Z = dot(x, f)
        if Z < -0.6:
            return None
        k = 2 * s / (1 + Z)
        return self.W / 2 + dot(x, r) * k, self.H / 2 - dot(x, u) * k

    def star(self, p, m, bv, lim):
        d = lim - m
        if d <= 0:
            return
        r, g, b = bv_rgb(bv)
        a = min(1.0, 0.3 + 0.15 * d)
        rad = 0.6 + 0.42 * d
        self.cv.create_oval(p[0] - rad, p[1] - rad, p[0] + rad, p[1] + rad, fill=hexc(255 * a * r, 255 * a * g, 255 * a * b), outline="")

    def redraw(self):
        cv = self.cv
        cv.delete("all")
        self.W, self.H = max(100, cv.winfo_width()), max(100, cv.winfo_height())
        R = self.R[self.kind]
        s = self.scn[self.kind]
        if R["phase"] == "run" and R.get("stage") == "read":
            cv.create_text(self.W / 2, self.H / 2, text=STAGES["read"], fill="#9aa3ab", font=("Malgun Gothic", 14, "bold"))
            return
        J = s["J0"] + s["days"] * R["frac"]
        if self.kind == 8:
            self.draw8(s, J)
        else:
            self.draw9(s, J)
        if self.solved:
            hh = " %02d:%s" % (int(s["hour"]), "30" if s["hour"] % 1 else "00") if self.kind == 8 else ""
            cv.create_text(12, 14, text=fmt_d(J) + hh, fill="#f3d58a", anchor="w", font=("Malgun Gothic", 10, "bold"))

    def draw8(self, s, J):
        cv = self.cv
        v = self.view[8]
        HM = frame_hm(s["J0"], J)
        B = self.basis(hvec(v["alt"], v["az"]), [0, 0, 1])
        for vv, m, bv in STARS:
            if m > 5.6:
                continue
            x = mv(HM, vv)
            if x[2] < 0:
                continue
            p = self.proj(B, x)
            if p and -5 < p[0] < self.W + 5 and -5 < p[1] < self.H + 5:
                self.star(p, m, bv, 6.2)
        for pl, m0, bv in (("jupiter", -2.2, 0.85), ("saturn", 0.6, 1.05), ("mars", 1.2, 1.5), ("venus", -4.0, 0.8)):
            x = mv(HM, body(pl, J))
            if x[2] > 0:
                p = self.proj(B, x)
                if p:
                    self.star(p, m0, bv, 6.2)
        sun = body("sun", J)
        mo = moon_at(s["J0"], J)
        mh = mv(HM, mo)
        if mh[2] > 0:
            p = self.proj(B, mh)
            if p:
                sp = unit3([sun[i] - dot(sun, mo) * mo[i] for i in range(3)])
                q = self.proj(B, mv(HM, unit3([mo[i] + 0.03 * sp[i] for i in range(3)])))
                self.moon(p, q, sep(mo, [-x for x in sun]), 13)
        pts = []
        for i in range(121):
            p = self.proj(B, hvec(0, v["az"] - 120 + i * 2))
            if p:
                pts += list(p)
        if len(pts) >= 4:
            cv.create_polygon(*(pts + [self.W + 50, self.H + 400, -50, self.H + 400]), fill="#07080b", outline="")
        for i, n in enumerate(T(["북", "동", "남", "서"], ["N", "E", "S", "W"])):
            p = self.proj(B, hvec(-3, i * 90))
            if p and 0 < p[0] < self.W:
                cv.create_text(p[0], min(self.H - 8, p[1] + 12), text=n, fill="#c9a24a", font=("Segoe UI", 10, "bold"))
        if self.solved:
            seg = []
            for k in range(int(s["days"] * 4) + 1):
                x = mv(HM, moon_at(s["J0"], s["J0"] + k / 4))
                p = self.proj(B, x) if x[2] > -0.05 else None
                if p:
                    seg += list(p)
                else:
                    if len(seg) >= 4:
                        cv.create_line(*seg, fill="#ff8a70", width=1.5)
                    seg = []
            if len(seg) >= 4:
                cv.create_line(*seg, fill="#ff8a70", width=1.5)
            self.labels(B, lambda w: mv(HM, w), lambda x: x[2] > 0.05)

    def moon(self, p, toward, phase, Rp):
        ang = math.atan2(toward[1] - p[1], toward[0] - p[0]) if toward else 0.0
        k = math.cos(phase * DEG)
        for rr, col in ((Rp * 3.2, "#0c0f15"), (Rp * 2.2, "#121620"), (Rp * 1.5, "#1a1f2b")):
            self.cv.create_oval(p[0] - rr, p[1] - rr, p[0] + rr, p[1] + rr, fill=col, outline="")
        self.cv.create_oval(p[0] - Rp, p[1] - Rp, p[0] + Rp, p[1] + Rp, fill="#2a2e38", outline="")
        pts = []
        for i in range(25):
            t = -math.pi / 2 + math.pi * i / 24
            pts.append((Rp * math.cos(t), Rp * math.sin(t)))
        for i in range(25):
            t = math.pi / 2 + math.pi * i / 24
            pts.append((k * Rp * math.cos(t), Rp * math.sin(t)))
        ca, sa = math.cos(ang), math.sin(ang)
        flat = []
        for x, y in pts:
            flat += [p[0] + x * ca - y * sa, p[1] + x * sa + y * ca]
        self.cv.create_polygon(*flat, fill="#f6f2e2", outline="")

    def draw9(self, s, J):
        cv = self.cv
        v = self.view[9]
        lc = s["lc"] + v["dl"]
        B = self.basis(ecl_vec(lc, v["db"]), ecl_vec(lc, 90))
        for vv, m, bv in STARS:
            if m > 5.6:
                continue
            p = self.proj(B, vv)
            if p and -5 < p[0] < self.W + 5 and -5 < p[1] < self.H + 5:
                self.star(p, m, bv, 6.2)
        if self.solved:
            for pl, col in (("sun", "#a08a40"), ("mars", "#d0705a"), ("venus", "#a8b8d8")):
                seg = []
                t = 0.0
                while t <= s["days"]:
                    p = self.proj(B, body(pl, s["J0"] + t))
                    if p:
                        seg += list(p)
                    t += 0.5
                if len(seg) >= 4:
                    cv.create_line(*seg, fill=col, width=1.4)
            self.labels(B, lambda w: w, lambda x: True)
        p = self.proj(B, body("sun", J))
        if p:
            for rr, col in ((30, "#2a2412"), (18, "#4a3e1a")):
                cv.create_oval(p[0] - rr, p[1] - rr, p[0] + rr, p[1] + rr, fill=col, outline="")
            cv.create_oval(p[0] - 9, p[1] - 9, p[0] + 9, p[1] + 9, fill="#ffe08a", outline="")
        for pl, m0, bv in (("mercury", -0.2, 0.9), ("venus", -4.2, 0.75), ("mars", 1.4, 1.55), ("jupiter", -2.0, 0.85), ("saturn", 0.6, 1.05)):
            p = self.proj(B, body(pl, J))
            if p:
                self.star(p, m0, bv, 6.6)
                if self.solved and pl in ("mars", "venus"):
                    cv.create_text(p[0] + 8, p[1] - 8, text="♂" if pl == "mars" else "♀", fill="#ff8a70" if pl == "mars" else "#cfe0ff", anchor="w", font=("Segoe UI", 10, "bold"))

    def labels(self, B, tf, ok):
        for c, rings in BOUNDS.items():
            sx = sy = sz = 0.0
            for r in rings:
                for ra, de in r:
                    w = vec(ra, de)
                    sx += w[0]
                    sy += w[1]
                    sz += w[2]
            x = tf(unit3([sx, sy, sz]))
            if not ok(x):
                continue
            p = self.proj(B, x)
            if p and 10 < p[0] < self.W - 10 and 10 < p[1] < self.H - 10:
                self.cv.create_text(p[0], p[1], text=c, fill="#7fb6e6", font=("Segoe UI", 9, "bold"))

    # ---- the solution
    def show_sol(self):
        if not messagebox.askyesno("IAO 2015", T("해답을 볼까요? 시험처럼 풀어 보려면 먼저 끝까지 풀어 보세요.", "Show the solution? To work it like the examination, finish first.")):
            return
        self.solved = True
        self.write_sol()

    def write_sol(self):
        k = self.kind
        s = self.scn[k]
        S = self.data["sheet"]
        line = (T("2015 장면(기본)", "2015 scene (default)") if s["seed"] == 2015 else T("연습 장면", "practice scene")) + ": " + fmt_d(s["J0"]) + " – " + fmt_d(s["J0"] + s["days"])
        head = T("원래 애니메이션과 공식 해답은 공개되지 않았습니다. 지금 장면에 대한 HaslaLab 해답 — 화면에 날짜, 경로, 별자리 이름이 나타납니다.\n\n",
                 "The original animation and the official solution were not published. HaslaLab's solution for the scene now chosen — the date, the paths and the constellation names appear on the dome.\n\n")
        if k == 8:
            m, months = self.keyc.setdefault(8, key8(s))
            fq, fm = const_of(moon_geo(s["Jfq"])[0]), const_of(moon_geo(s["Jfm"])[0])
            sun = const_of(sun_geo((s["Jfq"] + s["Jfm"]) / 2))
            mine = int(S["m8"]) if S.get("m8") else 0
            mark = "" if not mine else "✓" if mine == m else T("△ (장면이 걸친 달)", "△ (a month the scene touches)") if mine in months else "✗"
            txt = line + "\n\n8. " + MONTHS[m - 1] + ". " + T(
                "달이 상현일 때 %s, 보름일 때 %s에 있습니다. 상현달은 해보다 90° 동쪽, 보름달은 해의 정반대이므로 해는 %s에 있고, 해가 %s에 있는 때는 %s입니다." % (fq, fm, sun, sun, MONTHS[m - 1]),
                "At first quarter the Moon is in %s, at full in %s. The first-quarter Moon is 90° east of the Sun and the full Moon opposite it, so the Sun is in %s, which it is in %s." % (fq, fm, sun, MONTHS[m - 1])) + ("\n" + T("답: ", "Yours: ") + mark if mark else "")
        else:
            kk = self.keyc.setdefault(9, key9(s))

            def mk(x, J):
                if x is None:
                    return ""
                d = ddays(x, doy(J))
                return " ✓" if d <= 7 else " △" if d <= 14 else " ✗"

            def md(J):
                _, m, d = ymd(J)
                return "%d/%d" % (m, d)
            a, b = parse_md(S.get("d1", "")), parse_md(S.get("d2", ""))
            txt = line + "\n\n9.1 " + T("시작 ", "Beginning ") + md(s["J0"]) + mk(a, s["J0"]) + ", " + T("끝 ", "end ") + md(s["J0"] + s["days"]) + mk(b, s["J0"] + s["days"]) + T(
                " (월/일). 해는 처음에 %s, 끝에 %s에 있습니다. 해는 하루 약 1°씩 황도를 지나므로 별과 견준 해의 위치(황경 %.0f° → %.0f°)에서 날짜를 읽습니다(춘분 3/21 = 0°)." ,
                " (month/day). The Sun starts in %s and ends in %s. It moves about 1° a day along the ecliptic, so its place among the stars (longitude %.0f° → %.0f°) gives the date (vernal equinox 21 March = 0°).") % (
                kk["sun"][0], kk["sun"][-1], lam_of(sun_geo(s["J0"])), lam_of(sun_geo(s["J0"] + s["days"]))) + "\n\n9.2 ♂: " + " → ".join(kk["mars"]) + cmp_set(S.get("mars", ""), kk["mars"]) + "\n     ♀: " + " → ".join(kk["venus"]) + cmp_set(S.get("venus", ""), kk["venus"]) + "\n" + T(
                "가장 밝고 해에서 47° 넘게 떨어지지 않는 흰 점이 금성, 붉고 어두운 점이 화성입니다.", "The brightest white point, never more than 47° from the Sun, is Venus; the dimmer red one is Mars.")
        self.sol.configure(state="normal")
        self.sol.delete("1.0", "end")
        self.sol.insert("end", head + txt)
        self.sol.configure(state="disabled")


